INSERT IGNORE INTO polymers 
(name, category, description, strength, max_temperature, density, chemical_resistance, cost, advantages, limitations, applications, image_url)
VALUES
('HDPE', 'Thermoplastic', 'High-Density Polyethylene is a tough, highly crystalline commodity polymer offering superior chemical inertness, high moisture barrier, and excellent impact resistance.', 28.00, 120, 0.955, 'Excellent', 'Low', 'Outstanding chemical resistance, zero moisture absorption, high impact resistance, fully recyclable, very low cost.', 'Subject to environmental stress cracking under surfactants, high thermal expansion, low mechanical stiffness at elevated temperatures.', 'Water pipes, chemical storage tanks, food packaging, milk bottles, gas distribution piping, geomembranes, cutting boards.', NULL),
('LDPE', 'Thermoplastic', 'Low-Density Polyethylene is a highly branched, ductile thermoplastic known for its exceptional flexibility, high clarity in thin films, and waterproof characteristics.', 18.00, 80, 0.920, 'Excellent', 'Low', 'Exceptional flexibility and elongation, low density, high moisture barrier, great electrical insulation, economical.', 'Low tensile strength, low maximum continuous temperature, vulnerable to oil absorption and outdoor UV degradation.', 'Plastic bags, flexible squeeze bottles, packaging films, wire and cable jacketing, flexible tubing, agricultural mulch.', NULL),
('LLDPE', 'Thermoplastic', 'Linear Low-Density Polyethylene provides higher tensile strength, puncture resistance, and environmental stress crack resistance than conventional LDPE.', 24.00, 90, 0.925, 'Excellent', 'Low', 'High puncture and tear resistance, superior elongation, excellent impact strength down to subzero temperatures.', 'Narrower heat-sealing temperature window than LDPE, low surface hardness, low heat deflection.', 'Stretch film, pallet wrap, heavy-duty shipping bags, rotational molding containers, geomembranes, flexible tubing.', NULL),
('UHMWPE', 'High-Performance Polyethylene', 'Ultra-High Molecular Weight Polyethylene features extremely long polymer chains giving it the highest impact strength and lowest sliding friction of any thermoplastic.', 42.00, 90, 0.940, 'Excellent', 'Medium', 'Extreme wear and abrasion resistance, near-zero friction coefficient, self-lubricating, virtually unbreakable under impact.', 'Cannot be processed by conventional injection molding; requires compression molding or ram extrusion; low melt temperature.', 'Chute liners, conveyor wear strips, orthopedic joint implants, ballistic body armor fibers, marine fender pads, mechanical gears.', NULL),
('PP', 'Thermoplastic', 'Polypropylene is a lightweight semi-crystalline polymer with good chemical resistance, high stiffness, and unparalleled living hinge fatigue resistance.', 34.00, 105, 0.905, 'Excellent', 'Low', 'Lowest density among commodity plastics, exceptional fatigue endurance (living hinges), autoclavable, excellent chemical barrier.', 'Susceptible to UV degradation without carbon black or stabilizers; becomes brittle below 0 deg C; difficult to bond with adhesives.', 'Automotive bumpers, living hinges, food containers, medical syringes, battery casings, labware, chemical piping.', NULL),
('PP-Random Copolymer', 'Thermoplastic', 'Random Copolymer Polypropylene incorporates ethylene units into the chain to dramatically boost optical clarity and drop impact ductility.', 30.00, 95, 0.900, 'Good', 'Low', 'High optical transparency, smooth surface finish, good impact resistance at ambient temperatures, low extraction levels.', 'Slightly lower stiffness and melting point than PP homopolymer, moderate scratch resistance.', 'Clear food storage containers, medical syringes, pharmaceutical vials, consumer housewares, cosmetic jars.', NULL),
('PVC-Rigid', 'Thermoplastic', 'Rigid Polyvinyl Chloride (uPVC) is an unplasticized structural polymer with high modulus, inherent flame retardancy, and excellent weatherability.', 55.00, 60, 1.420, 'Good', 'Low', 'Inherently self-extinguishing flame resistance, high mechanical stiffness, outstanding outdoor weatherability, economical.', 'Low heat deflection temperature, releases corrosive hydrogen chloride gas if overheated, brittle under shock at cold temperatures.', 'Municipal water pipes, window profiles, exterior building siding, chemical ducting, drainage conduits, electrical junction boxes.', NULL),
('PVC-Flexible', 'Thermoplastic', 'Plasticized Polyvinyl Chloride contains plasticizers to deliver rubber-like flexibility, tear strength, and electrical insulation properties.', 20.00, 60, 1.300, 'Good', 'Low', 'Highly pliable, excellent dielectric insulation, fire retardant, easily weldable, resistant to moisture and acids.', 'Plasticizer migration over time can cause embrittlement; poor resistance to aromatic hydrocarbons and chlorinated solvents.', 'Electrical cable jacketing, medical IV tubing, blood bags, vinyl flooring, protective boots, inflatable curtains.', NULL),
('PS', 'Thermoplastic', 'General Purpose Polystyrene (GPPS) is an amorphous glassy polymer known for high optical clarity, excellent dimensional stability, and easy molding.', 45.00, 70, 1.050, 'Fair', 'Low', 'Crystal clear optical transparency, high surface gloss, rigid and dimensionally stable, low mold shrinkage.', 'Notoriously brittle under impact, poor solvent resistance, low heat resistance, prone to stress cracking.', 'Petri dishes, disposable cutlery, CD jewel cases, cosmetic packaging, retail display stands, diagnostic trays.', NULL),
('HIPS', 'Thermoplastic', 'High Impact Polystyrene combines polystyrene with polybutadiene rubber grafting to provide good impact resistance while keeping easy thermoformability.', 30.00, 75, 1.040, 'Fair', 'Low', 'Substantially improved impact toughness compared to GPPS, excellent thermoforming characteristics, low cost, easy to paint.', 'Opaque translucent white finish, poor outdoor UV resistance without additives, vulnerable to aromatic solvents.', 'Refrigerator interior door liners, consumer electronic housings, thermoformed food packaging trays, toys, signboards.', NULL),
('EPS', 'Cellular Polymer', 'Expanded Polystyrene is a closed-cell cellular foam consisting of 98% air, engineered for superior thermal insulation and shock-absorbing cushioning.', 8.00, 75, 0.030, 'Fair', 'Low', 'Ultra-lightweight, outstanding shock dampening, superior thermal insulation factor, moisture resistant, low cost.', 'Very low mechanical shear and tensile strength, dissolved easily by gasoline and organic solvents, bulky disposal footprint.', 'Building foundation insulation panels, protective packaging corners for electronics, bicycle helmets, cooler boxes.', NULL),
('PET', 'Thermoplastic', 'Polyethylene Terephthalate is a strong, lightweight semi-crystalline polyester offering exceptional carbon dioxide barrier properties and optical clarity.', 75.00, 70, 1.380, 'Good', 'Low', 'Superb gas and moisture barrier, high tensile strength, high transparency in biaxially oriented state, universally recyclable.', 'Subject to hydrolytic degradation during melt processing if not thoroughly dried; moderate continuous temperature resistance.', 'Carbonated beverage bottles, food jars, polyester textile fibers, food blister packs, strapping tape, optical films.', NULL),
('PETG', 'Thermoplastic', 'Polyethylene Terephthalate Glycol-modified is an amorphous polyester that does not crystallize, offering great clarity, toughness, and 3D printability.', 50.00, 65, 1.270, 'Good', 'Medium', 'Glass-like transparency, high impact strength even at low temperatures, easy thermoforming without pre-drying, excellent 3D print layer bonding.', 'Lower surface hardness than acrylic, prone to scratching, low glass transition temperature.', 'Medical equipment packaging, point-of-sale display stands, 3D printing filaments, electronic product covers, machine guards.', NULL),
('ABS', 'Engineering Thermoplastic', 'Acrylonitrile Butadiene Styrene is an opaque engineering terpolymer providing balanced toughness, dimensional stability, and electroplating capability.', 45.00, 85, 1.050, 'Fair', 'Medium', 'Exceptional impact resistance, high dimensional stability, easy to injection mold and machine, excellent electroplating and painting receptivity.', 'Moderate chemical resistance to solvents and esters; poor resistance to direct sunlight (UV) without stabilizers.', 'Automotive instrument panels, power tool housings, computer monitors, consumer electronics, LEGO bricks, protective helmets.', NULL),
('SAN', 'Engineering Thermoplastic', 'Styrene Acrylonitrile is a transparent copolymer providing higher heat resistance, tensile strength, and chemical resistance than standard polystyrene.', 68.00, 85, 1.080, 'Good', 'Medium', 'High optical transparency, superior surface scratch resistance, higher heat tolerance than PS, good grease resistance.', 'Moderate impact ductility, yellowing propensity with thermal degradation, sensitive to stress cracking under cyclic loads.', 'Blender jugs, refrigerator crisper drawers, cosmetic containers, water filter housings, automotive tail-lamp lenses.', NULL),
('ASA', 'Engineering Thermoplastic', 'Acrylonitrile Styrene Acrylate replaces the butadiene rubber in ABS with acrylate rubber to achieve outstanding outdoor UV and weather resistance.', 48.00, 90, 1.070, 'Good', 'Medium', 'Remarkable outdoor UV weather resistance, retains color and gloss without painting, good impact resistance, high thermal stability.', 'Slightly higher cost than ABS, hygroscopic requiring drying before processing, moderate solvent resistance.', 'Automotive exterior side mirrors, radiator grilles, exterior architectural siding, outdoor electrical enclosures, marine equipment.', NULL),
('Nylon 6', 'Engineering Thermoplastic', 'Polyamide 6 (Nylon 6) is a semi-crystalline engineering thermoplastic known for high mechanical strength, good dampening, and high wear resistance.', 80.00, 120, 1.140, 'Good', 'Medium', 'High toughness and tensile strength, excellent fatigue endurance, self-lubricating wear properties, good resistance to fuels and oils.', 'High moisture absorption reduces dimensional stability and tensile modulus while increasing impact flexibility.', 'Gears, sliding bearings, automotive engine covers, power tool housings, textile fibers, cable zip ties, fasteners.', NULL),
('Nylon 66', 'Engineering Thermoplastic', 'Polyamide 66 provides higher stiffness, higher melting point (265 deg C), and lower creep under high loads than Nylon 6.', 85.00, 130, 1.150, 'Good', 'Medium', 'Higher heat deflection temperature and tensile modulus than PA6, excellent abrasion resistance, great hydrocarbon resistance.', 'Absorbs ambient moisture leading to dimensional expansion, requires thorough drying before molding, relatively high mold shrinkage.', 'Under-the-hood automotive radiator tanks, mechanical gears, bearing cages, circuit breaker housings, industrial valves, cable clips.', NULL),
('Nylon 11', 'Engineering Thermoplastic', 'Polyamide 11 is a bio-based engineering polymer derived from castor oil, offering extremely low moisture absorption and superior cold impact toughness.', 55.00, 110, 1.040, 'Excellent', 'High', 'Significantly lower moisture absorption than PA6/66, outstanding dimensional stability, exceptional flexibility down to -40 deg C, renewable source.', 'Lower tensile strength and stiffness than PA66, higher price point due to specialty precursor synthesis.', 'Automotive fuel and air-brake lines, offshore oil and gas flexible umbilicals, 3D printing SLS powder, ski boot shells.', NULL),
('Nylon 12', 'Engineering Thermoplastic', 'Polyamide 12 has the lowest moisture absorption and lowest density of all standard polyamides, guaranteeing high dimensional precision in humid environments.', 50.00, 105, 1.020, 'Excellent', 'High', 'Minimal moisture uptake, superior dimensional precision, high burst pressure resistance, excellent dampening of vibration and noise.', 'Lower mechanical strength and heat resistance than PA66, relatively high cost.', 'Automotive fuel delivery lines, pneumatic tubing, precision water meter housings, athletic equipment, SLS 3D printed functional prototypes.', NULL),
('Nylon 46', 'High-Temp Polyamide', 'Polyamide 46 has an exceptionally high symmetrical chain structure, yielding rapid crystallization, high melting point (295 deg C), and high stiffness at high heat.', 100.00, 160, 1.180, 'Good', 'High', 'Exceptional mechanical stiffness and strength retention at elevated temperatures up to 160 deg C, outstanding fatigue resistance.', 'Very high moisture absorption rate requiring careful dry-room handling, premium price tag.', 'Automotive starter motor gears, timing chain tensioner guides, electric motor brush holders, heavy-duty clutch components.', NULL),
('POM-C', 'Engineering Thermoplastic', 'Polyoxymethylene Copolymer (Acetal Copolymer) is an engineering plastic renowned for high dimensional stability, low friction, and resistance to thermal degradation.', 65.00, 100, 1.410, 'Excellent', 'Medium', 'Exceptional dimensional stability, very low moisture uptake, low friction coefficient, excellent resistance to hydrolysis and alkaline chemicals.', 'High mold shrinkage, difficult to bond without chemical etching, susceptible to degradation by strong oxidizing acids.', 'Precision gears, conveyor rollers, fuel sender units, water filtration valves, aerosol valves, zipper fasteners.', NULL),
('POM-H', 'Engineering Thermoplastic', 'Polyoxymethylene Homopolymer (Delrin) provides higher tensile strength, rigidity, and fatigue endurance than POM copolymer.', 75.00, 105, 1.430, 'Good', 'Medium', 'Higher tensile strength, higher surface hardness, superior fatigue resistance, low sliding wear against metals.', 'Susceptible to centerline porosity in thick cross-sections, lower resistance to strong hot bases than POM copolymer.', 'High-load gear trains, actuator cams, safety belt lock mechanisms, sliding door rollers, musical instrument components.', NULL),
('Polycarbonate', 'Engineering Thermoplastic', 'Polycarbonate is an amorphous high-performance thermoplastic offering near-glass transparency, remarkable impact toughness, and high heat resistance.', 65.00, 125, 1.200, 'Fair', 'Medium', 'Virtually unbreakable impact resistance, crystal clarity (88% light transmission), high heat deflection temperature, flame retardant grades available.', 'Susceptible to stress cracking from solvents and alkaline cleaners; low scratch resistance without hardcoatings.', 'Bulletproof security glazing, automotive headlamp lenses, safety goggles, electronic display screens, medical device housings.', NULL),
('PMMA', 'Engineering Thermoplastic', 'Polymethyl Methacrylate (Acrylic) is an amorphous optical plastic known for exceptional light transmission (92%), UV stability, and surface gloss.', 70.00, 85, 1.190, 'Fair', 'Medium', 'Highest optical clarity of all plastics, outstanding natural UV resistance without yellowing, high scratch resistance compared to PC.', 'Brittle under impact compared to polycarbonate, poor chemical resistance to acetone and aromatic hydrocarbons.', 'Automotive tail-light clusters, commercial signage, aircraft window glazing, optical lenses, aquarium display panels, daylight fixtures.', NULL),
('PBT', 'Engineering Thermoplastic', 'Polybutylene Terephthalate is a semi-crystalline polyester characterized by fast crystallization cycles, high electrical resistance, and low moisture absorption.', 60.00, 120, 1.310, 'Excellent', 'Medium', 'Rapid molding cycle times, excellent dielectric breakdown resistance, low moisture absorption, high dimensional stability.', 'Susceptible to hot water hydrolysis above 60 deg C, notch-sensitive under impact without glass fiber reinforcement.', 'Automotive ignition coil bobbins, electrical plug connectors, keyboard keycaps, fiber optic buffer tubes, distributor caps.', NULL),
('PPE/PPO', 'Engineering Thermoplastic', 'Polyphenylene Ether is an amorphous high-heat polymer with negligible moisture absorption and very stable electrical properties across frequencies.', 65.00, 110, 1.060, 'Good', 'Medium', 'Extremely low moisture absorption (<0.07%), very high hydrolytic stability, dimensional precision, flame retardant.', 'High melt viscosity requires blending with polystyrene (Noryl) to achieve good melt processability.', 'Water pump impellers, solar junction boxes, telecommunication relay housings, automotive wheel covers, battery brackets.', NULL),
('PEEK', 'High-Performance Polymer', 'Polyether Ether Ketone is an elite semi-crystalline polymer providing exceptional strength, continuous service at 250 deg C, and chemical inertness.', 100.00, 250, 1.300, 'Excellent', 'High', 'Continuous operation at 250 deg C, outstanding chemical resistance across nearly all acids and bases, gamma radiation resistant, low smoke/flame.', 'Very high cost, high melt processing temperatures (>370 deg C) requiring specialized mold heating equipment.', 'Aerospace structural brackets, oil and gas downhole drilling tools, spine implant cages, semiconductor wafer carriers, engine bearings.', NULL),
('PEKK', 'High-Performance Polymer', 'Polyetherketoneketone offers higher glass transition temperature, higher compressive strength, and slower crystallization kinetics than PEEK.', 110.00, 260, 1.310, 'Excellent', 'High', 'Higher Tg (160 deg C) than PEEK, superior compressive and wear resistance, flame retardant (UL94 V-0), ideal for 3D printing.', 'Premium cost, requires specialized high-temperature processing equipment.', 'Aerospace interior panels, carbon fiber composite matrices, oilfield valve seals, high-voltage electrical isolators.', NULL),
('PEI', 'High-Performance Polymer', 'Polyetherimide (Ultem) is an amorphous amber-transparent polymer providing high heat resistance, inherent flame retardancy, and high dielectric strength.', 105.00, 170, 1.270, 'Good', 'High', 'Continuous operating temperature of 170 deg C, high dielectric strength, intrinsically flame retardant with low smoke generation.', 'High raw material price, sensitive to certain chlorinated and ketone solvents under mechanical stress.', 'Aircraft interior lighting housings, medical sterilizer trays, fiber optic connectors, printed circuit test fixtures.', NULL),
('PPS', 'High-Performance Polymer', 'Polyphenylene Sulfide is a semi-crystalline polymer noted for supreme chemical inertness, high modulus, and zero known solvents below 200 deg C.', 85.00, 220, 1.350, 'Excellent', 'High', 'Continuous temperature capability to 220 deg C, no known solvent below 200 deg C, inherently flame retardant, high dimensional precision.', 'Brittle in unfilled form (almost always compounded with glass or mineral fillers), abrasive to standard tooling.', 'Automotive engine coolant pumps, exhaust gas recirculation valves, industrial chemical pump casings, electrical motor insulators.', NULL),
('PES', 'High-Performance Polymer', 'Polyethersulfone is an amorphous transparent amber plastic offering continuous high-temperature endurance, high creep resistance, and sterilizability.', 85.00, 180, 1.370, 'Good', 'High', 'High continuous service temperature of 180 deg C, withstands repeated steam sterilization cycles, high electrical insulation.', 'Vulnerable to stress cracking in the presence of polar organic solvents, relatively expensive.', 'Dialysis membrane filters, medical surgical lamp reflectors, aircraft interior window surrounds, hot water meter housings.', NULL),
('PSU', 'High-Performance Polymer', 'Polysulfone is an amorphous rigid transparent thermoplastic known for exceptional hydrolytic stability in boiling water and repeated steam cycles.', 70.00, 150, 1.240, 'Good', 'High', 'Withstands repeated steam autoclaving, low creep under continuous load, transparent with slight amber hue, FDA food-contact compliant.', 'Sensitive to aromatic hydrocarbons, esters, and ketones; requires high melt processing temperatures.', 'Medical surgical instrument handles, dairy equipment tubing manifolds, hot beverage dispenser valves, battery cell containers.', NULL),
('PPSU', 'High-Performance Polymer', 'Polyphenylsulfone (Radel) is a high-performance sulfone polymer offering the highest impact toughness and chemical resistance in the sulfone family.', 75.00, 180, 1.290, 'Excellent', 'High', 'Survives over 1,000 steam sterilization cycles without loss of impact toughness, high chemical resistance, high heat deflection.', 'Premium cost among sulfone polymers, high mold temperatures required.', 'Surgical trial implants, dental tool handles, aircraft galley food service carts, hot water plumbing manifolds.', NULL),
('PAI', 'Ultra-High-Performance Polymer', 'Polyamide-imide (Torlon) provides the highest mechanical tensile and compressive strength of any unreinforced thermoplastic up to 260 deg C.', 150.00, 260, 1.410, 'Excellent', 'High', 'Extreme mechanical strength up to 260 deg C, extraordinary wear and friction performance, unmatched dimensional creep resistance.', 'Requires a lengthy post-curing thermal cycle (several days) to achieve full molecular weight; very high cost.', 'Transmission thrust washers, aerospace mechanical actuators, labyrinth seals, plasma torch insulators, semiconductor test sockets.', NULL),
('Polyimide-Thermoset', 'High-Performance Thermoset', 'Thermoset Polyimide (Vespel SP-1) is a non-melting polymeric material capable of continuous operation from cryogenic temperatures up to 300 deg C.', 90.00, 300, 1.430, 'Excellent', 'High', 'Continuous operation at 300 deg C (short excursions to 480 deg C), zero melt point, high vacuum outgassing resistance, self-lubricating.', 'Must be processed via powder metallurgy compaction and sintering; cannot be melt molded; very expensive.', 'Jet engine variable stator vane bushings, high-vacuum semiconductor wafer clamps, cryogenic valve seats, spacecraft thermal isolators.', NULL),
('LCP', 'High-Performance Polymer', 'Liquid Crystal Polymer possesses rigid rod-like molecular chains that align during flow, providing incredible thin-wall flow and heat resistance.', 140.00, 240, 1.400, 'Excellent', 'High', 'Outstanding melt flow enabling ultra-thin walls (<0.2 mm), near-zero mold shrinkage, withstands SMT lead-free solder reflow temperatures.', 'Weak weld-line strength due to high anisotropic molecular orientation, high directional property variance.', 'Ultra-miniature smartphone SIM card connectors, camera module brackets, fiber optic transceivers, automotive ignition components.', NULL),
('PBI', 'Ultra-High-Performance Polymer', 'Polybenzimidazole offers the highest temperature resistance and mechanical strength retention of any commercially available polymer up to 340 deg C.', 160.00, 340, 1.300, 'Excellent', 'High', 'Highest continuous service temperature (340 deg C), extreme compressive strength, will not burn in normal air, low thermal conductivity.', 'Extremely difficult to machine, very brittle, highly expensive, processed only via specialized sintered powder techniques.', 'Aerospace rocket motor nozzles, deep-well oil recovery valve seals, extreme-temperature glass handling suction cups.', NULL),
('PAEK', 'High-Performance Polymer', 'Polyaryletherketone is an engineered ketone variant designed for optimized crystallization rates and high stiffness in continuous carbon fiber tapes.', 105.00, 250, 1.300, 'Excellent', 'High', 'Faster cycle times than standard PEEK, high toughness, superior fatigue strength in structural composite laminates.', 'Requires specialized high-temperature consolidation tools, expensive raw polymer feedstock.', 'Aerospace composite fuselage stiffeners, military helicopter rotor components, primary structural composite brackets.', NULL),
('PTFE', 'Fluoropolymer', 'Polytetrafluoroethylene (Teflon) is a fully fluorinated polymer offering near-total chemical inertness, extreme non-stick, and continuous service to 260 deg C.', 25.00, 260, 2.160, 'Excellent', 'High', 'Almost universal chemical inertness, lowest coefficient of friction among solids, broad temperature window (-200 to +260 deg C), non-stick.', 'Subject to cold flow (creep) under continuous load, cannot be melt injection molded, low tensile strength, high density.', 'Chemical pipe gaskets, non-stick cooking surfaces, low-friction sleeve bearings, pharmaceutical valve diaphragms, high-frequency coax cable insulation.', NULL),
('PVDF', 'Fluoropolymer', 'Polyvinylidene Fluoride is a high-purity melt-processable fluoropolymer with superior mechanical stiffness, chemical barrier, and UV resistance.', 50.00, 150, 1.780, 'Excellent', 'High', 'Melt processable via injection molding, high mechanical strength for a fluoropolymer, high purity (low extractables), piezoelectric grades.', 'Attacked by strong fuming acids, ketones, and strong bases at high temperatures; high density.', 'Ultra-pure water piping for semiconductor fabs, chemical tank linings, lithium-ion battery binder membranes, outdoor architectural coatings.', NULL),
('FEP', 'Fluoropolymer', 'Fluorinated Ethylene Propylene is a melt-processable copolymer of tetrafluoroethylene, retaining PTFE-like chemical resistance with optical clarity.', 22.00, 200, 2.150, 'Excellent', 'High', 'Fully melt processable, high optical clarity and UV transmission, continuous 200 deg C resistance, exceptional non-stick release.', 'Lower continuous temperature than PTFE (200 vs 260 deg C), low tensile modulus, subject to creep under sustained pressure.', 'Plenum cable jacketing, chemical process sight glasses, 3D printing SLA resin vat release films, solar panel protective films.', NULL),
('PFA', 'Fluoropolymer', 'Perfluoroalkoxy Alkane delivers the full 260 deg C heat and chemical performance of PTFE with the convenience of melt injection processability.', 28.00, 260, 2.150, 'Excellent', 'High', 'Continuous 260 deg C performance, melt injection moldable, extraordinary flex-fatigue life, ultra-high chemical purity.', 'Very high cost, requires corrosion-resistant nickel-alloy tooling during melt processing due to trace fluorinated off-gassing.', 'Semiconductor chemical tubing, high-purity chemical valve bodies, fluid transfer fittings, heat exchanger tubing.', NULL),
('ETFE', 'Fluoropolymer', 'Ethylene Tetrafluoroethylene combines fluoropolymer chemical resistance with high mechanical toughness, tear strength, and high light transmission.', 45.00, 150, 1.700, 'Excellent', 'High', 'High light transmission (95%), self-cleaning exterior surface, exceptional tear and puncture resistance, 1% the weight of glass.', 'Lower continuous heat capability than fully fluorinated polymers, specialized welding techniques required for installation.', 'Architectural stadium roofs (Allianz Arena, Eden Project), chemical pump impellers, wire and cable wrap, greenhouse membranes.', NULL),
('ECTFE', 'Fluoropolymer', 'Ethylene Chlorotrifluoroethylene (Halar) is an engineered fluoropolymer with supreme surface smoothness, chemical resistance, and chlorine barrier.', 50.00, 150, 1.680, 'Excellent', 'High', 'Exceptional chemical resistance across broad pH scale (1-14), ultra-smooth surface preventing bacterial adhesion, high abrasion resistance.', 'Higher price than PVDF, requires high melt processing temperatures.', 'Chemical exhaust ductwork, pulp and paper chlorine bleach piping, powder coating for aggressive chemical tanks, pharmaceutical fluid systems.', NULL),
('PCTFE', 'Fluoropolymer', 'Polychlorotrifluoroethylene provides the lowest water vapor transmission rate of any polymer and maintains ductility down to cryogenic temperatures (-240 deg C).', 40.00, 150, 2.120, 'Excellent', 'High', 'Lowest moisture and gas vapor permeability among all plastics, zero outgassing, retains mechanical seal elasticity at liquid nitrogen temperatures.', 'Extremely sensitive to thermal degradation during molding; high cost.', 'Cryogenic liquid oxygen and nitrogen valve seats, pharmaceutical moisture-barrier blister packaging (Aclar), aerospace aerospace fuel seals.', NULL),
('PVF', 'Fluoropolymer', 'Polyvinyl Fluoride (Tedlar) is a specialty fluoropolymer film known for decades-long outdoor weatherability, graffiti resistance, and flame barrier.', 70.00, 110, 1.450, 'Good', 'High', 'Decades of proven UV and weather protection without cracking, impervious to harsh cleaning solvents, flame and smoke retardant.', 'Supplied primarily as oriented film rather than bulk molding resin, requires specialized lamination adhesives.', 'Photovoltaic solar module backsheets, aircraft cabin wall coverings, outdoor architectural graphics, acoustic wall protective facings.', NULL),
('Epoxy-Standard', 'Thermoset', 'Bisphenol-A based Epoxy Resin cured with amine hardeners forms a crosslinked polymer network with high bond strength and low shrinkage.', 75.00, 120, 1.180, 'Good', 'Medium', 'Exceptional adhesion to metals and fibers, negligible cure shrinkage (<1%), high mechanical stiffness, excellent electrical insulation.', 'Brittle without toughening modifiers, slow cure cycles compared to thermoplastic molding, skin-sensitizing liquid precursors.', 'Carbon fiber composite structural parts, printed circuit board substrates (FR-4), structural engineering adhesives, marine repairs.', NULL),
('Epoxy-High-Temperature', 'Thermoset', 'Multifunctional epoxy resin formulated with aromatic amine curing agents to achieve glass transition temperatures exceeding 180 deg C.', 90.00, 180, 1.250, 'Excellent', 'High', 'Retains structural modulus up to 180 deg C, excellent hot-wet compression strength, high chemical resistance to aviation fuels.', 'Requires multi-stage autoclave curing cycles at elevated temperature and pressure, inherently brittle.', 'Aerospace composite primary structures (wing spars, control surfaces), motorsport drive shafts, tooling prepregs.', NULL),
('Phenolic-Resin', 'Thermoset', 'Phenol-Formaldehyde Resin (Bakelite) is a historic thermoset renowned for supreme fire resistance, high surface hardness, and electrical insulation.', 55.00, 150, 1.400, 'Good', 'Low', 'Remarkable flame resistance with low smoke toxicity, high heat deflection, excellent electrical arc resistance, economical.', 'Dark colors only (brown/black), releases condensation water during curing, brittle under mechanical shock.', 'Automotive brake pads and clutch facings, cookware pot handles, electrical switchboards, billiard balls, circuit breaker cases.', NULL),
('Melamine-Formaldehyde', 'Thermoset', 'Melamine-Formaldehyde is a hard, scratch-resistant thermosetting resin with exceptional surface gloss, heat resistance, and fire retardancy.', 65.00, 130, 1.500, 'Good', 'Low', 'Glass-hard scratch-resistant surface, self-extinguishing flame properties, can be colored in vibrant white and pastel shades.', 'Brittle, cannot be heated in microwave ovens, releases trace formaldehyde if subjected to high boiling acids.', 'Kitchen dinnerware, Formica decorative laminate countertops, electrical switch plates, acoustic insulation foam.', NULL),
('Urea-Formaldehyde', 'Thermoset', 'Urea-Formaldehyde is a cost-effective amino resin widely utilized for high-hardness electrical components and wood composite binders.', 50.00, 90, 1.450, 'Fair', 'Low', 'High surface hardness, superior anti-tracking electrical resistance, self-extinguishing, highly economical.', 'Poor water and weather resistance; susceptible to hydrolytic breakdown under warm, damp environments.', 'Wall electrical sockets and light switches, particleboard and MDF binder adhesive, toilet seat covers, buttons.', NULL),
('Unsaturated-Polyester', 'Thermoset', 'Unsaturated Polyester Resin is the dominant binder matrix for glass-reinforced plastic (fiberglass) boat hulls, tanks, and architectural panels.', 55.00, 110, 1.200, 'Good', 'Low', 'Very low cost, easy ambient-temperature curing with MEKP initiator, rapid wetting of glass fibers, good water resistance.', 'Significant cure volumetric shrinkage (6-8%), styrene vapor emissions during hand layup, lower fatigue strength than epoxy.', 'Fiberglass boat hulls, automotive body repair fillers, architectural cladding panels, corrugated roofing sheets, shower trays.', NULL),
('Vinyl-Ester', 'Thermoset', 'Vinyl Ester Resin bridges the gap between polyester and epoxy, offering exceptional chemical corrosion resistance and dynamic fatigue life.', 70.00, 135, 1.150, 'Excellent', 'Medium', 'Superior chemical corrosion resistance to aggressive acids and alkalis, higher elongation than polyester, prevents fiberglass osmotic blistering.', 'Higher cost than unsaturated polyester, contains styrene monomer requiring positive shop ventilation.', 'Chemical plant storage tanks, wastewater piping, flue gas desulfurization scrubbers, marine luxury yacht hulls, swimming pools.', NULL),
('Cyanate-Ester', 'High-Performance Thermoset', 'Cyanate Ester resins offer exceptionally low dielectric loss (Dk/Df), minimal moisture uptake, and high radiation resistance for satellite applications.', 95.00, 230, 1.200, 'Excellent', 'High', 'Extremely low dielectric constant and dissipation factor across GHz microwave frequencies, outgassing compliant for space vacuum.', 'Expensive raw materials, sensitive to moisture contamination prior to complete thermal curing.', 'Satellite radar antennas, stealth aircraft radomes, high-frequency printed microwave circuit substrates, space telescope mirror structures.', NULL),
('Bismaleimide', 'High-Performance Thermoset', 'Bismaleimide (BMI) resins are thermosetting polymers designed for continuous aerodynamic surface service temperatures between 200 and 230 deg C.', 105.00, 230, 1.280, 'Excellent', 'High', 'Retains high mechanical stiffness and compression after impact at 200 deg C, excellent hot-wet performance, epoxy-like handling.', 'High raw material cost, brittle without core-shell rubber or reactive thermoplastic toughening modifiers.', 'Supersonic fighter jet fuselage skins, jet engine nacelle cowlings, high-temperature missile fairings, F1 exhaust surrounds.', NULL),
('Polyurethane-Rigid', 'Thermoset Cellular', 'Rigid Polyurethane Foam is the highest efficiency commercial thermal insulation material available, created by reacting polyols with isocyanates.', 15.00, 110, 0.045, 'Good', 'Low', 'Lowest thermal conductivity (highest R-value) of commercial insulation materials, closed-cell structure prevents moisture ingress.', 'Flammable without halogen or phosphorus flame retardants, degrades rapidly under direct UV sun exposure.', 'Commercial refrigerator insulation, architectural insulated metal sandwich panels, pipe insulation, spray foam roofing.', NULL),
('TPU', 'Thermoplastic Elastomer', 'Thermoplastic Polyurethane bridges the gap between rubber and plastics, offering extreme abrasion resistance, elasticity, and oil barrier.', 40.00, 90, 1.200, 'Good', 'Medium', 'Outstanding abrasion and tear resistance, high elastic recovery, remains flexible at -40 deg C, good grease and fuel resistance.', 'Prone to hydrolytic degradation in prolonged hot humid environments, narrow melt processing temperature window.', 'Athletic shoe soles, protective smartphone cases, hydraulic cylinder seals, pneumatic hoses, automotive suspension bushings, caster wheels.', NULL),
('TPO', 'Thermoplastic Elastomer', 'Thermoplastic Polyolefin is a blend of polypropylene and uncrosslinked EPDM rubber providing lightweight durability and cold-impact toughness.', 22.00, 95, 0.950, 'Good', 'Low', 'Low density, excellent cold impact down to -40 deg C, direct paintability with primers, fully recyclable, cost effective.', 'Moderate tensile strength, lower recovery from high sustained compression stress than vulcanized rubbers.', 'Automotive bumper fascias, single-ply commercial roofing membranes, interior automotive dash skins, weatherstrip seals.', NULL),
